. (Join-Path $PSScriptRoot 'TestHarness.ps1')
$script:N=0;function A($id,$ok,$m){$script:N++;if(!$ok){throw "$id failed: $m"};Write-Host "$id PASS $m"};$e=[pscustomobject]@{CanonicalKey='doi:10.1234/rap.001';ZoteroItemId='Z1';Title='Research Intake Safety';FirstAuthor='Kim';Year='2026'}
$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @($e) @();A LU01 ($x.CanonicalStatus-eq'AVAILABLE') 'canonical exact match';$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @() @();A LU02 ($x.CanonicalStatus-eq'NONE') 'canonical not found';$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @($e,$e) @();A LU03 ($s.CanonicalPapers.Count-eq2) 'multiple canonical matches retained for ambiguity';$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @() @($e);A LU04 ($x.ZoteroStatus-eq'AVAILABLE') 'Zotero exact match';$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @() @();A LU05 ($x.ZoteroStatus-eq'NONE') 'Zotero not found';$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s PASS @() @($e,$e);A LU06 ($s.ZoteroItems.Count-eq2) 'multiple Zotero matches retained for ambiguity';foreach($z in @(@('LU07','TIMEOUT'),@('LU08','MALFORMED'),@('LU09','AUTH_FAILURE'),@('LU10','PARTIAL'))){$s=New-RapResearchIntakeStore PR015;$x=Invoke-RapResearchIntakeReadOnlyLookup $s $z[1];A $z[0] ($x.Status-eq'LOOKUP_FAILED'-and$s.Decisions.Count-eq0-and$s.Counters.ZoteroCreateDecision-eq0) "$($z[1]) cannot become absent/create"}
if($script:N-ne10){throw 'Expected LU01-LU10'};Write-Host 'SPR-015 Turn B lookup matrix: LU01-LU10 10/10 PASS; mutations 0/0/0'
